import re
from enum import Enum, auto

class ExpressionError(Exception):
    pass

class TokenType(Enum):
    NUMBER = auto()
    PLUS = auto()
    MINUS = auto()
    MULTIPLY = auto()
    DIVIDE = auto()
    LPAREN = auto()
    RPAREN = auto()
    EOF = auto()

class Token:
    def __init__(self, type_, value=None):
        self.type = type_
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value!r})"

class Lexer:
    def __init__(self, text):
        self.text = text
        self.pos = 0

    def error(self, msg):
        raise ExpressionError(f"{msg} at position {self.pos}")

    def skip_whitespace(self):
        while self.pos < len(self.text) and self.text[self.pos].isspace():
            self.pos += 1

    def peek(self):
        if self.pos >= len(self.text):
            return None
        return self.text[self.pos]

    def advance(self):
        char = self.text[self.pos]
        self.pos += 1
        return char

    def tokenize(self):
        tokens = []
        while self.pos < len(self.text):
            self.skip_whitespace()
            if self.pos >= len(self.text):
                break

            char = self.peek()

            if char.isdigit() or char == '.':
                tokens.append(self.read_number())
            elif char == '+':
                tokens.append(Token(TokenType.PLUS))
                self.advance()
            elif char == '-':
                tokens.append(Token(TokenType.MINUS))
                self.advance()
            elif char == '*':
                tokens.append(Token(TokenType.MULTIPLY))
                self.advance()
            elif char == '/':
                tokens.append(Token(TokenType.DIVIDE))
                self.advance()
            elif char == '(':
                tokens.append(Token(TokenType.LPAREN))
                self.advance()
            elif char == ')':
                tokens.append(Token(TokenType.RPAREN))
                self.advance()
            else:
                self.error(f"Unexpected character: '{char}'")

        tokens.append(Token(TokenType.EOF))
        return tokens

    def read_number(self):
        start = self.pos
        has_dot = False
        while self.pos < len(self.text) and (self.text[self.pos].isdigit() or (self.text[self.pos] == '.' and not has_dot)):
            if self.text[self.pos] == '.':
                has_dot = True
            self.pos += 1

        num_str = self.text[start:self.pos]
        if not num_str or num_str == '.':
            self.error(f"Invalid number: '{num_str}'")

        return Token(TokenType.NUMBER, float(num_str))

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def current(self):
        return self.tokens[self.pos]

    def eat(self, token_type):
        if self.current().type == token_type:
            token = self.current()
            self.pos += 1
            return token
        raise ExpressionError(f"Expected {token_type}, got {self.current()}")

    def parse_expression(self):
        result = self.parse_term()

        while self.current().type in (TokenType.PLUS, TokenType.MINUS):
            op = self.current()
            self.pos += 1
            right = self.parse_term()
            if op.type == TokenType.PLUS:
                result += right
            else:
                result -= right

        return result

    def parse_term(self):
        result = self.parse_factor()

        while self.current().type in (TokenType.MULTIPLY, TokenType.DIVIDE):
            op = self.current()
            self.pos += 1
            right = self.parse_factor()
            if op.type == TokenType.MULTIPLY:
                result *= right
            else:
                if right == 0:
                    raise ExpressionError("Division by zero")
                result /= right

        return result

    def parse_factor(self):
        token = self.current()

        if token.type == TokenType.PLUS:
            self.pos += 1
            return +self.parse_factor()

        if token.type == TokenType.MINUS:
            self.pos += 1
            return -self.parse_factor()

        if token.type == TokenType.NUMBER:
            self.pos += 1
            return token.value

        if token.type == TokenType.LPAREN:
            self.pos += 1
            result = self.parse_expression()
            self.eat(TokenType.RPAREN)
            return result

        raise ExpressionError(f"Unexpected token: {token}")

def evaluate(expr: str) -> float:
    if not expr or not expr.strip():
        raise ExpressionError("Empty expression")

    lexer = Lexer(expr)
    tokens = lexer.tokenize()

    parser = Parser(tokens)
    result = parser.parse_expression()

    if parser.current().type != TokenType.EOF:
        raise ExpressionError(f"Unexpected token after expression: {parser.current()}")

    return result
